import { $authHost, $host } from "./index";

export const changeType = async (id, name) => {
    const {data} = await $authHost.put('api/type/' + id, name)
    return data
}

export const removeType = async (id) => {
    const {data} = await $authHost.delete('api/type/' + id)
    return data
}
